import json
r=json.load(open("results/r2_analyses.json",encoding="utf-8")); L=[]
h=r["H3_HT"]; L.append(f"[HT-based H3] HT {h['HT']*100:.2f}% minus M1 share {h['M1_share']*100:.2f}% = {h['diff']*100:.2f} points (95% stratified bootstrap CI {h['ci'][0]*100:.2f}-{h['ci'][1]*100:.2f})")
d=r["stratum_D_exact"]; L.append(f"[Stratum D exact] {d['pos']}/{d['n']} positives; Clopper-Pearson 95% CI of rate {d['cp_ci'][0]:.4f}-{d['cp_ci'][1]:.4f}; implied frame positives {d['implied_frame_positives'][0]:.0f} (lower) / {d['implied_frame_positives'][1]:.0f} (point) / {d['implied_frame_positives'][2]:.0f} (upper); contribution to frame share {d['implied_frame_share_contribution_pct'][0]:.2f}-{d['implied_frame_share_contribution_pct'][1]:.2f} points")
a=r["ablation_2x2_F1"]; L.append(f"[2x2 ablation M5 F1] weighted@0.5={a['weighted@0.5']:.3f}; weighted@fold-tuned threshold={a['weighted@cv']:.3f}; unweighted@0.5={a['unweighted@0.5']:.3f}; unweighted@tuned={a['unweighted@cv']:.3f}  (so EITHER removing weights OR tuning the threshold restores F1; the failure is the fixed 0.5 threshold on design-weighted training)")
for k,v in r["dsl_lpm_diagnosis"].items(): L.append(f"[DSL-LPM diagnosis {k}] beta={v['beta_pp']:.1f} pp, SE={v['se_pp']:.1f} pp, cond(A)={v['cond']:.3g}, pseudo-outcome range {v['xt_min']:.1f}..{v['xt_max']:.1f}")
L.append("[Single-bid share by procedure type, regression sample] " + "; ".join(f"{p}: n={x['n']}, {x['single_share']*100:.1f}%" for p,x in r["single_bid_by_procedure"].items()))
o=r["open_procedures_only"]; L.append(f"[Open procedures only, full controls] M1 naive {o['M1_naive']['beta_pp']:.1f} pp (CI {o['M1_naive']['ci_pp'][0]:.1f} to {o['M1_naive']['ci_pp'][1]:.1f}), M2 naive {o['M2_naive']['beta_pp']:.1f} (CI {o['M2_naive']['ci_pp'][0]:.1f} to {o['M2_naive']['ci_pp'][1]:.1f}), n={o['M1_naive']['n']}; labelled-only {o['labelled_only']['beta_pp']:.1f} (CI {o['labelled_only']['ci_pp'][0]:.1f} to {o['labelled_only']['ci_pp'][1]:.1f}, n={o['labelled_only']['n']}); DSL with M5 {o['DSL_M5']['beta_pp']:.1f} pp (SE {o['DSL_M5']['se_pp']:.1f}); max pseudo-outcome {o['DSL_M5']['xt_max']:.1f} (no heavily weighted stratum-D positive in this subsample)")
s=r["selection"]; L.append(f"[Selection] regression sample n={s['regression']['n']}: M1 share {s['regression']['M1_share']*100:.2f}%, M2 {s['regression']['M2_share']*100:.2f}%, English {s['regression']['share_ENG']*100:.1f}%; excluded frame notices n={s['excluded']['n']}: M1 {s['excluded']['M1_share']*100:.2f}%, M2 {s['excluded']['M2_share']*100:.2f}%, English {s['excluded']['share_ENG']*100:.1f}%")
open("results/r2_digest.txt","w",encoding="utf-8").write("\n".join(L)); print("\n".join(L))
